-- ============================================================================
-- SOURCE: supabase/migrations/20260806120000_extensions_and_helpers.sql
-- ============================================================================

-- ClouDonna Platform — Database Foundation
-- Migration 01: extensions and shared helper functions
--
-- Every later migration depends on this one. It sets up:
--   1. UUID generation and vector (embedding) support.
--   2. A single, reusable `set_updated_at()` trigger function so `updated_at`
--      maintenance is never duplicated per-table.
--   3. `organization_members` comes later (tenancy migration), but the RLS
--      helper functions that depend on it are declared there, not here —
--      kept next to the table they query for discoverability.

-- pgcrypto gives us gen_random_uuid(); it is enabled by default on Supabase
-- projects, but declared explicitly so this migration set is portable to any
-- plain Postgres instance.
create extension if not exists pgcrypto;

-- pgvector — required for every `embedding` column added in later
-- migrations (semantic search / RAG). Enabled here, once, platform-wide.
create extension if not exists vector;

-- Generic updated_at maintenance. Attached per-table via
-- `create trigger ... before update ... execute function set_updated_at()`.
-- Kept intentionally dumb: it only touches updated_at, never any other
-- column, so it can never become a place business logic accretes.
create or replace function set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

comment on function set_updated_at() is
  'Shared BEFORE UPDATE trigger: stamps updated_at = now(). Attached to every mutable table. No business logic — see docs/platform/database-architecture.md.';

-- ============================================================================
-- SOURCE: supabase/migrations/20260806120100_enums.sql
-- ============================================================================

-- ClouDonna Platform — Database Foundation
-- Migration 02: enumerated types
--
-- Every fixed vocabulary in the schema is declared here, once, instead of
-- being re-typed as a CHECK constraint per table. Two families:
--
--   (a) Vocabularies that already exist as TypeScript union types in the
--       Donna AI scoring engine (apps/web/src/components/donna-ai/**, built
--       in Sprint 3, not yet persisted anywhere). Kept in lockstep with
--       those types by design — this schema is the eventual persistence
--       target for that in-memory model. Where TypeScript uses camelCase
--       (e.g. "aiReadiness"), the SQL enum uses snake_case instead
--       ("ai_readiness"); translating between the two is the repository
--       layer's job, not the database's.
--   (b) Platform vocabularies that don't exist in the TypeScript layer yet
--       because nothing has needed them until this migration (tenancy
--       roles, session status, verification status, etc).

-- (a) Aligned with apps/web .../vendor-intelligence/types.ts MaturityBand
create type maturity_band as enum ('emerging', 'developing', 'established', 'leading');

-- (a) Aligned with .../scoring/types.ts ScoreDimensionKey
create type score_dimension_key as enum (
  'architecture', 'business', 'technology', 'governance', 'ai_readiness',
  'security', 'ecosystem', 'cost', 'time_to_value', 'strategic'
);

-- (a) Aligned with .../vendor-intelligence/types.ts
create type cloud_model as enum ('single-cloud', 'multi-cloud', 'hybrid', 'on-premise-capable');
create type deployment_model as enum ('saas', 'paas', 'iaas', 'managed-service', 'self-hosted');
create type cost_tier as enum ('entry', 'mid', 'premium', 'enterprise-custom');
create type implementation_complexity as enum ('low', 'medium', 'high', 'very-high');
create type time_to_value_band as enum ('weeks', '1-3-months', '3-6-months', '6-plus-months');
create type lock_in_risk as enum ('low', 'medium', 'high', 'very-high');
create type platform_category as enum (
  'data-platform', 'hyperscale-cloud', 'operational-database',
  'enterprise-legacy', 'decision-ops-intelligence'
);

-- (a) Aligned with apps/web .../donna-ai/types.ts. Deliberately NOT the same
-- pattern as `industries` (a reference table, extensible without a
-- migration) — employee_band, trait and goal_tag are small, closed
-- vocabularies wired directly into the deterministic scoring engine's
-- matching logic, so a fixed enum is the honest representation: adding a
-- new trait is a code change to the scoring engine anyway, not just a data
-- change.
create type employee_band as enum ('smb', 'mid-market', 'enterprise', 'global-enterprise');
create type goal_tag as enum (
  'modernization', 'business-ai', 'planning', 'governance',
  'data-products', 'cost-reduction', 'compliance', 'innovation'
);
create type trait as enum (
  'sap-native', 'governed-data', 'modern-architecture', 'multi-cloud',
  'enterprise-scale', 'cost-efficient', 'ai-ready', 'azure-aligned',
  'aws-aligned', 'gcp-aligned', 'hyperscale-infra', 'operational-workload',
  'high-touch-enterprise', 'legacy-integration', 'vendor-neutral'
);

-- (b) Tenancy
create type organization_member_role as enum ('owner', 'admin', 'member', 'viewer');

-- (b) Decision engine
create type decision_session_status as enum ('draft', 'in_progress', 'completed', 'archived');
create type constraint_type as enum (
  'budget', 'timeline', 'risk_appetite', 'preferred_cloud',
  'preferred_vendor', 'internal_skills', 'other'
);

-- (b) Trust and provenance — every recommendation traces back to evidence,
-- and not all evidence carries the same weight. Used by evidence_sources so
-- the UI/report layer can visibly distinguish "vendor's own claim" from
-- "independent analyst report" rather than presenting both as equally
-- authoritative (a neutrality requirement carried over from the Sprint 3
-- vendor-intelligence model).
create type evidence_reliability_tier as enum (
  'primary_source', 'vendor_published', 'analyst_report', 'community', 'internal_review'
);

-- (b) Partner ecosystem
create type verification_status as enum ('unverified', 'pending', 'verified', 'rejected');

-- (b) AI conversations — the message role, not the conversation's business
-- meaning. See docs for why AI Conversations/Messages exist in this schema
-- even though OpenAI integration itself is explicitly out of scope here.
create type ai_message_role as enum ('system', 'user', 'assistant', 'tool');

-- ============================================================================
-- SOURCE: supabase/migrations/20260806120200_tenancy.sql
-- ============================================================================

-- ClouDonna Platform — Database Foundation
-- Migration 03: tenancy (organizations, users, membership, workspaces, projects)
--
-- Tenant hierarchy: organization -> workspace -> project. `organization_id`
-- is denormalized onto workspaces and projects (not just derivable via a
-- join) so every RLS policy in every later migration is a single equality
-- check against `organization_id`, never a multi-hop join. This is a
-- deliberate trade against strict normalization, made once, here, and
-- reused by every table that follows.
--
-- Authentication is explicitly out of scope for this migration set (see
-- docs/platform/database-architecture.md). `users` is a standalone profile
-- table today; the seam for wiring it to Supabase Auth is documented but
-- not built.

create table organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid, -- FK added after `users` exists, below
  constraint organizations_name_not_blank check (btrim(name) <> '')
);

comment on table organizations is
  'The tenant root. Everything in the platform that is not shared reference data hangs off an organization, directly or via workspace/project.';

create unique index organizations_slug_key on organizations (slug) where deleted_at is null;
create index organizations_created_by_idx on organizations (created_by);

create trigger organizations_set_updated_at
  before update on organizations
  for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table users (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  full_name text,
  avatar_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint users_email_not_blank check (btrim(email) <> '')
);

comment on table users is
  'Standalone profile table, deliberately not yet wired to Supabase Auth. In production this row''s id is expected to equal the corresponding auth.users.id (created via a sync trigger added when authentication is implemented) — no such trigger exists yet, by design. Cross-organization: a user''s org memberships live in organization_members, not here.';

create unique index users_email_key on users (lower(email)) where deleted_at is null;
create index users_created_by_idx on users (created_by);

create trigger users_set_updated_at
  before update on users
  for each row execute function set_updated_at();

alter table organizations
  add constraint organizations_created_by_fkey
  foreign key (created_by) references users (id) on delete set null;

-- ---------------------------------------------------------------------------

create table organization_members (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  user_id uuid not null references users (id) on delete cascade,
  role organization_member_role not null default 'member',
  invited_by uuid references users (id) on delete set null,
  joined_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null
);

comment on table organization_members is
  'Join table between users and organizations, carrying the role that drives every RLS policy in this schema. A user removed from an org gets deleted_at set here, not a hard delete, so membership history survives.';

create unique index organization_members_org_user_key
  on organization_members (organization_id, user_id) where deleted_at is null;
create index organization_members_user_idx on organization_members (user_id) where deleted_at is null;
create index organization_members_org_idx on organization_members (organization_id) where deleted_at is null;
create index organization_members_created_by_idx on organization_members (created_by);
create index organization_members_invited_by_idx on organization_members (invited_by);

create trigger organization_members_set_updated_at
  before update on organization_members
  for each row execute function set_updated_at();

-- RLS helper functions. SECURITY DEFINER so they can read organization_members
-- regardless of the calling role's own RLS grants, without exposing the table
-- itself — the standard Supabase pattern for avoiding recursive RLS policies.
create or replace function is_org_member(org_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from organization_members m
    where m.organization_id = org_id
      and m.user_id = auth.uid()
      and m.deleted_at is null
  );
$$;

comment on function is_org_member(uuid) is
  'RLS predicate: true if the current auth.uid() is an active member of org_id. Returns false (not an error) when auth.uid() is null, i.e. before authentication exists — every tenant-scoped table is closed by default until Sprint auth work wires up real sessions.';

create or replace function is_org_admin(org_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from organization_members m
    where m.organization_id = org_id
      and m.user_id = auth.uid()
      and m.role in ('owner', 'admin')
      and m.deleted_at is null
  );
$$;

comment on function is_org_admin(uuid) is
  'RLS predicate: true if the current auth.uid() is an owner/admin member of org_id. Used for membership and organization-settings mutations.';

alter table organizations enable row level security;
alter table users enable row level security;
alter table organization_members enable row level security;

-- organizations: members can read their own org; only admins can update it;
-- no INSERT/DELETE policy for regular roles — org creation and hard deletes
-- are service-role (backend) operations, not something any authenticated
-- user can self-serve yet.
create policy organizations_select on organizations
  for select using (deleted_at is null and is_org_member(id));

create policy organizations_update on organizations
  for update using (deleted_at is null and is_org_admin(id));

-- users: a user can always read/update their own profile row; org admins can
-- read the profiles of members of their own org (needed for member lists).
create policy users_select_self on users
  for select using (deleted_at is null and id = auth.uid());

create policy users_select_org_admin on users
  for select using (
    deleted_at is null
    and exists (
      select 1 from organization_members m
      where m.user_id = users.id
        and m.deleted_at is null
        and is_org_admin(m.organization_id)
    )
  );

create policy users_update_self on users
  for update using (deleted_at is null and id = auth.uid());

-- organization_members: members can see their org's roster; only admins can
-- change roles or add/remove members.
create policy organization_members_select on organization_members
  for select using (deleted_at is null and is_org_member(organization_id));

create policy organization_members_insert on organization_members
  for insert with check (is_org_admin(organization_id));

create policy organization_members_update on organization_members
  for update using (deleted_at is null and is_org_admin(organization_id));

-- ---------------------------------------------------------------------------

create table workspaces (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  name text not null,
  slug text not null,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint workspaces_name_not_blank check (btrim(name) <> '')
);

comment on table workspaces is
  'A sub-division within an organization (e.g. a business unit or region). Optional layer between an organization and its projects — most organizations will only ever need one.';

create unique index workspaces_org_slug_key
  on workspaces (organization_id, slug) where deleted_at is null;
create index workspaces_org_idx on workspaces (organization_id) where deleted_at is null;
create index workspaces_created_by_idx on workspaces (created_by);

create trigger workspaces_set_updated_at
  before update on workspaces
  for each row execute function set_updated_at();

alter table workspaces enable row level security;

create policy workspaces_select on workspaces
  for select using (deleted_at is null and is_org_member(organization_id));

create policy workspaces_insert on workspaces
  for insert with check (is_org_member(organization_id));

create policy workspaces_update on workspaces
  for update using (deleted_at is null and is_org_member(organization_id));

-- ---------------------------------------------------------------------------

create table projects (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  workspace_id uuid not null references workspaces (id) on delete cascade,
  name text not null,
  slug text not null,
  description text,
  is_archived boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint projects_name_not_blank check (btrim(name) <> '')
);

comment on table projects is
  'The unit customers actually work inside day to day — a specific initiative (e.g. "2027 Data Platform RFP"). Decision sessions belong to a project.';

create unique index projects_workspace_slug_key
  on projects (workspace_id, slug) where deleted_at is null;
create index projects_org_idx on projects (organization_id) where deleted_at is null;
create index projects_workspace_idx on projects (workspace_id) where deleted_at is null;
create index projects_created_by_idx on projects (created_by);

create trigger projects_set_updated_at
  before update on projects
  for each row execute function set_updated_at();

alter table projects enable row level security;

create policy projects_select on projects
  for select using (deleted_at is null and is_org_member(organization_id));

create policy projects_insert on projects
  for insert with check (is_org_member(organization_id));

create policy projects_update on projects
  for update using (deleted_at is null and is_org_member(organization_id));

-- ============================================================================
-- SOURCE: supabase/migrations/20260806120300_taxonomy.sql
-- ============================================================================

-- ClouDonna Platform — Database Foundation
-- Migration 04: shared taxonomy (global reference data, not tenant-scoped)
--
-- Every table in this migration is platform-wide, curated by ClouDonna, and
-- shared by every organization — deliberately with NO organization_id
-- column. This is the first of several migrations that intentionally
-- deviate from "every table gets organization_id": a vendor category or an
-- industry definition is not owned by one tenant, the same way a country
-- list isn't. See docs/platform/database-architecture.md, "Global reference
-- data vs. tenant-scoped data", for the full rationale.
--
-- RLS on these tables is read-open (anyone, including unauthenticated
-- `anon`, can SELECT non-deleted rows — this is public catalog data) and
-- write-closed (no INSERT/UPDATE policy for any role, so only the
-- `service_role` key, used by the curation/repository layer, can write).

create table vendor_categories (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint vendor_categories_name_not_blank check (btrim(name) <> '')
);

comment on table vendor_categories is
  'Top-level market category a product competes in, e.g. "Data Cloud Platform", "ERP". Coarser than platform_category (the SQL enum used for architecture-level comparability); this is the label shown to a human browsing the catalog.';

create unique index vendor_categories_slug_key on vendor_categories (slug) where deleted_at is null;
create trigger vendor_categories_set_updated_at before update on vendor_categories for each row execute function set_updated_at();

create table industries (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint industries_name_not_blank check (btrim(name) <> '')
);

comment on table industries is
  'Controlled vocabulary of industries, e.g. "Financial Services", "Manufacturing". Referenced by decision sessions (as business context), products (as industry fit), and customer references.';

create unique index industries_slug_key on industries (slug) where deleted_at is null;
create trigger industries_set_updated_at before update on industries for each row execute function set_updated_at();

create table use_cases (
  id uuid primary key default gen_random_uuid(),
  industry_id uuid references industries (id) on delete set null,
  name text not null,
  slug text not null,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint use_cases_name_not_blank check (btrim(name) <> '')
);

comment on table use_cases is
  'A named, concrete scenario (e.g. "Real-time fraud detection"), optionally tied to one industry. Used to connect a business goal to the technology and architecture patterns that typically serve it.';

create unique index use_cases_slug_key on use_cases (slug) where deleted_at is null;
create index use_cases_industry_idx on use_cases (industry_id) where deleted_at is null;
create trigger use_cases_set_updated_at before update on use_cases for each row execute function set_updated_at();

create table architecture_patterns (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint architecture_patterns_name_not_blank check (btrim(name) <> '')
);

comment on table architecture_patterns is
  'A named structural approach (e.g. "Data Mesh", "Centralized Lakehouse", "Hub-and-Spoke Integration"), independent of any specific vendor. Solution Approaches in the Discovery flow are architecture patterns before a technology is named.';

create unique index architecture_patterns_slug_key on architecture_patterns (slug) where deleted_at is null;
create trigger architecture_patterns_set_updated_at before update on architecture_patterns for each row execute function set_updated_at();

create table technology_patterns (
  id uuid primary key default gen_random_uuid(),
  architecture_pattern_id uuid references architecture_patterns (id) on delete set null,
  name text not null,
  slug text not null,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint technology_patterns_name_not_blank check (btrim(name) <> '')
);

comment on table technology_patterns is
  'A named technology-level approach that implements an architecture pattern (e.g. "Event streaming with CDC" implementing "Data Mesh"), still independent of any specific vendor product. Products are matched to technology patterns, not the other way around.';

create unique index technology_patterns_slug_key on technology_patterns (slug) where deleted_at is null;
create index technology_patterns_arch_pattern_idx on technology_patterns (architecture_pattern_id) where deleted_at is null;
create trigger technology_patterns_set_updated_at before update on technology_patterns for each row execute function set_updated_at();

create table capabilities (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint capabilities_name_not_blank check (btrim(name) <> '')
);

comment on table capabilities is
  'Controlled vocabulary of capabilities a solution might need to provide (e.g. "Real-time Governance", "Row-Level Security", "Multi-Cloud Portability"). The bridge between a business goal and a product: goals imply required capabilities, products declare which capabilities they support and how well (product_capabilities, in the vendor-catalog migration).';

create unique index capabilities_slug_key on capabilities (slug) where deleted_at is null;
create trigger capabilities_set_updated_at before update on capabilities for each row execute function set_updated_at();

-- created_by index, uniform across all six tables above — supports both
-- "everything created by this user" lookups and the ON DELETE SET NULL
-- cascade from users, which otherwise has to sequentially scan each table.
do $$
declare
  t text;
begin
  foreach t in array array[
    'vendor_categories', 'industries', 'use_cases',
    'architecture_patterns', 'technology_patterns', 'capabilities'
  ]
  loop
    execute format('create index %I_created_by_idx on %I (created_by)', t, t);
  end loop;
end $$;

-- RLS: uniform read-open / write-closed policy across all six tables above.
do $$
declare
  t text;
begin
  foreach t in array array[
    'vendor_categories', 'industries', 'use_cases',
    'architecture_patterns', 'technology_patterns', 'capabilities'
  ]
  loop
    execute format('alter table %I enable row level security', t);
    execute format(
      'create policy %I_public_select on %I for select using (deleted_at is null)',
      t, t
    );
  end loop;
end $$;

-- ============================================================================
-- SOURCE: supabase/migrations/20260806120400_vendor_catalog.sql
-- ============================================================================

-- ClouDonna Platform — Database Foundation
-- Migration 05: vendor catalog (global reference data)
--
-- `products` is the persistence target for the Sprint 3 in-memory
-- VendorPlatformProfile catalog (apps/web/.../vendor-intelligence/catalog.ts,
-- currently 10 hardcoded TypeScript objects). Column names and enum types
-- mirror that type field-for-field so a future migration script can move
-- the data across with no reshaping. Nothing in this migration reads from
-- or writes to that TypeScript file — the alignment is a naming discipline,
-- not a runtime dependency.
--
-- Like taxonomy, this migration is global reference data: no
-- organization_id, read-open RLS, write-closed to service_role only.

create table vendors (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  description text,
  founded_year smallint,
  headquarters_country text,
  website_url text,
  logo_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint vendors_name_not_blank check (btrim(name) <> '')
);

comment on table vendors is
  'The company behind one or more products, e.g. "Snowflake Inc.". Kept separate from products because one vendor can offer several distinct products (SAP is both "SAP Business Data Cloud" and, eventually, other SAP products in this catalog).';

create unique index vendors_slug_key on vendors (slug) where deleted_at is null;
create index vendors_created_by_idx on vendors (created_by);
create trigger vendors_set_updated_at before update on vendors for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table products (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references vendors (id) on delete cascade,
  vendor_category_id uuid references vendor_categories (id) on delete set null,
  platform_category platform_category not null,
  name text not null,
  slug text not null,

  short_description text,
  executive_positioning text,
  ideal_customer_profile text,
  executive_summary text,

  ideal_use_cases text[] not null default '{}',
  anti_patterns text[] not null default '{}',
  typical_strengths text[] not null default '{}',
  typical_weaknesses text[] not null default '{}',
  migration_scenarios text[] not null default '{}',
  architecture_characteristics text[] not null default '{}',

  cloud_model cloud_model not null,
  deployment_models deployment_model[] not null default '{}',

  governance maturity_band,
  security maturity_band,
  compliance maturity_band,
  ai_capabilities maturity_band,
  machine_learning maturity_band,
  generative_ai maturity_band,
  ecosystem_strength maturity_band,
  partner_network maturity_band,
  sap_integration maturity_band,
  erp_integration maturity_band,
  crm_integration maturity_band,
  data_warehouse_integration maturity_band,
  multi_cloud_support maturity_band,
  lakehouse_capabilities maturity_band,
  data_virtualization maturity_band,
  data_sharing maturity_band,
  metadata_management maturity_band,
  master_data_management maturity_band,
  streaming maturity_band,

  implementation_complexity implementation_complexity,
  time_to_value time_to_value_band,
  vendor_lock_in_risk lock_in_risk,

  pricing_model text,
  cost_tier cost_tier,
  cost_characteristics text,

  company_size_fit employee_band[] not null default '{}',
  integration_strengths text[] not null default '{}',
  traits trait[] not null default '{}',

  source_notes text,
  last_reviewed_date date,

  -- text-embedding-3-small dimensionality (1536). Populated by a future
  -- ingestion job, not by this migration — see docs, "AI-readiness".
  embedding vector(1536),

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint products_name_not_blank check (btrim(name) <> '')
);

comment on table products is
  'One evaluable platform/product in the catalog, e.g. "Snowflake" or "SAP Business Data Cloud". All maturity_band columns are curated editorial judgments, never fabricated numbers, market share, or live pricing — see source_notes and last_reviewed_date. Numeric scores are never stored here; they are computed per decision_session into decision_scores.';

create unique index products_slug_key on products (slug) where deleted_at is null;
create index products_vendor_idx on products (vendor_id) where deleted_at is null;
create index products_vendor_category_idx on products (vendor_category_id) where deleted_at is null;
create index products_platform_category_idx on products (platform_category) where deleted_at is null;
create index products_traits_idx on products using gin (traits) where deleted_at is null;
create index products_embedding_idx on products using hnsw (embedding vector_cosine_ops);
create index products_created_by_idx on products (created_by);

create trigger products_set_updated_at before update on products for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table product_industries (
  product_id uuid not null references products (id) on delete cascade,
  industry_id uuid not null references industries (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (product_id, industry_id)
);

comment on table product_industries is
  'Which industries a product is a typical fit for (VendorPlatformProfile.industryFit). A join table against the industries reference table rather than an array column, since industries is itself an extensible catalog, not a closed enum.';

create index product_industries_industry_idx on product_industries (industry_id);

alter table product_industries enable row level security;
create policy product_industries_public_select on product_industries for select using (true);

-- ---------------------------------------------------------------------------

create table product_capabilities (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products (id) on delete cascade,
  capability_id uuid not null references capabilities (id) on delete cascade,
  maturity_band maturity_band not null,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null
);

comment on table product_capabilities is
  'How well a product supports a given capability from the shared capabilities taxonomy, and why. This is what business_goals ultimately get matched against, one level removed from a raw product-to-goal comparison: goal -> required capability -> product_capabilities.maturity_band.';

create unique index product_capabilities_product_capability_key
  on product_capabilities (product_id, capability_id) where deleted_at is null;
create index product_capabilities_capability_idx on product_capabilities (capability_id) where deleted_at is null;
create index product_capabilities_created_by_idx on product_capabilities (created_by);

create trigger product_capabilities_set_updated_at before update on product_capabilities for each row execute function set_updated_at();

alter table product_capabilities enable row level security;
create policy product_capabilities_public_select on product_capabilities for select using (deleted_at is null);

-- ---------------------------------------------------------------------------

create table analyst_reports (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  publisher text not null,
  published_at date,
  url text,
  summary text,
  embedding vector(1536),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint analyst_reports_title_not_blank check (btrim(title) <> '')
);

comment on table analyst_reports is
  'Citation metadata for a third-party analyst report (e.g. a named Gartner or Forrester publication) used as evidence. Stores only bibliographic metadata and an optional summary written by ClouDonna — never a reproduced rating, quadrant position, or score, which would be fabricated/licensed data this platform does not have rights to restate.';

create index analyst_reports_embedding_idx on analyst_reports using hnsw (embedding vector_cosine_ops);
create index analyst_reports_created_by_idx on analyst_reports (created_by);
create trigger analyst_reports_set_updated_at before update on analyst_reports for each row execute function set_updated_at();

alter table analyst_reports enable row level security;
create policy analyst_reports_public_select on analyst_reports for select using (deleted_at is null);

-- ---------------------------------------------------------------------------

create table customer_references (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products (id) on delete cascade,
  industry_id uuid references industries (id) on delete set null,
  use_case_id uuid references use_cases (id) on delete set null,
  company_name text,
  is_public boolean not null default false,
  summary text,
  source_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null
);

comment on table customer_references is
  'A case study or reference customer for a product. `is_public` false + null company_name supports anonymized references ("a global manufacturer") when a named case study is not available/permitted — the UI must never display a company name that was not explicitly marked public.';

create index customer_references_product_idx on customer_references (product_id) where deleted_at is null;
create index customer_references_industry_idx on customer_references (industry_id) where deleted_at is null;
create index customer_references_use_case_idx on customer_references (use_case_id) where deleted_at is null;
create index customer_references_created_by_idx on customer_references (created_by);

create trigger customer_references_set_updated_at before update on customer_references for each row execute function set_updated_at();

alter table customer_references enable row level security;
create policy customer_references_public_select on customer_references
  for select using (deleted_at is null and is_public = true);

alter table vendors enable row level security;
create policy vendors_public_select on vendors for select using (deleted_at is null);

alter table products enable row level security;
create policy products_public_select on products for select using (deleted_at is null);

-- ============================================================================
-- SOURCE: supabase/migrations/20260806120500_partner_ecosystem.sql
-- ============================================================================

-- ClouDonna Platform — Database Foundation
-- Migration 06: partner ecosystem (global reference data)
--
-- Backs the /for-partners journey (apps/web, Web Presence Sprint): a
-- consultancy or systems integrator surfaces against a specific product
-- they're certified/experienced in, not as a generic directory listing.

create table partner_companies (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null,
  description text,
  website_url text,
  regions text[] not null default '{}',
  specialties text[] not null default '{}',
  verification_status verification_status not null default 'unverified',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint partner_companies_name_not_blank check (btrim(name) <> '')
);

comment on table partner_companies is
  'A consultancy or systems integrator, independent of which specific products they implement (that link is implementation_partners). verification_status gates whether the company is shown publicly — see docs/platform/database-architecture.md, "Verification status".';

create unique index partner_companies_slug_key on partner_companies (slug) where deleted_at is null;
create index partner_companies_created_by_idx on partner_companies (created_by);
create trigger partner_companies_set_updated_at before update on partner_companies for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table implementation_partners (
  id uuid primary key default gen_random_uuid(),
  partner_company_id uuid not null references partner_companies (id) on delete cascade,
  product_id uuid not null references products (id) on delete cascade,
  certification_level text,
  verification_status verification_status not null default 'unverified',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null
);

comment on table implementation_partners is
  'Join between a partner company and a specific product they deliver, e.g. "Acme Consulting implements Snowflake". certification_level is free text because certification tiers/names are vendor-defined (Snowflake''s tiers are not SAP''s), not a shared cross-vendor vocabulary.';

create unique index implementation_partners_company_product_key
  on implementation_partners (partner_company_id, product_id) where deleted_at is null;
create index implementation_partners_product_idx on implementation_partners (product_id) where deleted_at is null;
create index implementation_partners_created_by_idx on implementation_partners (created_by);

create trigger implementation_partners_set_updated_at before update on implementation_partners for each row execute function set_updated_at();

alter table partner_companies enable row level security;
create policy partner_companies_public_select on partner_companies
  for select using (deleted_at is null and verification_status = 'verified');

alter table implementation_partners enable row level security;
create policy implementation_partners_public_select on implementation_partners
  for select using (deleted_at is null and verification_status = 'verified');

-- ============================================================================
-- SOURCE: supabase/migrations/20260806120600_decision_engine.sql
-- ============================================================================

-- ClouDonna Platform — Database Foundation
-- Migration 07: the decision engine core (tenant-scoped)
--
-- This is the persistence layer for the ClouDonna Decision Framework:
--   Business Goal -> Capabilities -> Requirements -> Constraints
--   -> Solution/Technology (Recommendations + Decision Scores)
--   -> Decision Report
-- Every table here belongs to exactly one organization. organization_id is
-- denormalized onto every table (not just derived via decision_session_id)
-- for single-join RLS, per the tenancy migration's stated design.
--
-- decision_frameworks/decision_framework_dimensions is the persistence
-- target for the Sprint 3 SCORE_WEIGHTS / SCORE_DIMENSION_LABELS constants
-- (apps/web/.../scoring/weights.ts) — today those are a hardcoded
-- TypeScript record; here they become data, and organizations get the
-- option to define their own weighting in the future without a code change.

create table decision_frameworks (
  id uuid primary key default gen_random_uuid(),
  -- null = a platform-wide default framework, visible to every org.
  -- not null = an org-specific customization. See docs, "Hybrid global/
  -- tenant tables".
  organization_id uuid references organizations (id) on delete cascade,
  name text not null,
  slug text not null,
  description text,
  version integer not null default 1,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint decision_frameworks_name_not_blank check (btrim(name) <> '')
);

comment on table decision_frameworks is
  'A named, versioned scoring methodology — which dimensions exist and how they''re weighted (decision_framework_dimensions). The seeded platform default corresponds exactly to today''s Donna Score v2 model (10 dimensions, weights summing to 1.0).';

create unique index decision_frameworks_org_slug_key
  on decision_frameworks (coalesce(organization_id, '00000000-0000-0000-0000-000000000000'::uuid), slug)
  where deleted_at is null;
create index decision_frameworks_org_idx on decision_frameworks (organization_id) where deleted_at is null;
create index decision_frameworks_created_by_idx on decision_frameworks (created_by);
create trigger decision_frameworks_set_updated_at before update on decision_frameworks for each row execute function set_updated_at();

create table decision_framework_dimensions (
  id uuid primary key default gen_random_uuid(),
  framework_id uuid not null references decision_frameworks (id) on delete cascade,
  dimension_key score_dimension_key not null,
  label text not null,
  weight numeric(4,3) not null check (weight >= 0 and weight <= 1),
  display_order smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references users (id) on delete set null
);

comment on table decision_framework_dimensions is
  'One row per scoring dimension within a framework. The application layer, not the database, is responsible for checking that weights sum to 1.0 for a given framework — see docs, "No business logic inside the database".';

create unique index decision_framework_dimensions_key
  on decision_framework_dimensions (framework_id, dimension_key);
create index decision_framework_dimensions_created_by_idx on decision_framework_dimensions (created_by);
create trigger decision_framework_dimensions_set_updated_at before update on decision_framework_dimensions for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table decision_sessions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  workspace_id uuid not null references workspaces (id) on delete cascade,
  project_id uuid not null references projects (id) on delete cascade,
  framework_id uuid references decision_frameworks (id) on delete set null,
  title text not null,
  status decision_session_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint decision_sessions_title_not_blank check (btrim(title) <> '')
);

comment on table decision_sessions is
  'One run of the Discovery -> Recommendation flow for a specific project — the aggregate root that business_goals, requirements, constraints, recommendations, decision_scores and decision_reports all hang off. Corresponds to a single completed Donna AI assessment today, generalized beyond the current single-form UI.';

create index decision_sessions_project_idx on decision_sessions (project_id) where deleted_at is null;
create index decision_sessions_org_idx on decision_sessions (organization_id) where deleted_at is null;
create index decision_sessions_status_idx on decision_sessions (status) where deleted_at is null;
create index decision_sessions_workspace_idx on decision_sessions (workspace_id) where deleted_at is null;
create index decision_sessions_framework_idx on decision_sessions (framework_id) where deleted_at is null;
create index decision_sessions_created_by_idx on decision_sessions (created_by);
-- Supports "recent sessions for this project" — a genuinely common list
-- view — as an index-only sort instead of a sort-after-scan.
create index decision_sessions_project_created_at_idx
  on decision_sessions (project_id, created_at desc) where deleted_at is null;
create trigger decision_sessions_set_updated_at before update on decision_sessions for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table business_goals (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  decision_session_id uuid not null references decision_sessions (id) on delete cascade,
  goal_tag goal_tag,
  custom_goal_text text,
  priority smallint,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint business_goals_has_content check (goal_tag is not null or custom_goal_text is not null)
);

comment on table business_goals is
  'The starting point of every session, deliberately first in the schema''s dependency chain, mirroring the framework''s "goal first" principle. Supports both the fixed goal_tag vocabulary (today''s wizard) and free-text goals (custom_goal_text), since a business-first platform cannot limit real customers to 8 pre-set tags.';

create index business_goals_session_idx on business_goals (decision_session_id) where deleted_at is null;
create index business_goals_org_idx on business_goals (organization_id) where deleted_at is null;
create index business_goals_created_by_idx on business_goals (created_by);
create trigger business_goals_set_updated_at before update on business_goals for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table decision_session_capabilities (
  decision_session_id uuid not null references decision_sessions (id) on delete cascade,
  capability_id uuid not null references capabilities (id) on delete cascade,
  priority text not null default 'must-have' check (priority in ('must-have', 'nice-to-have')),
  created_at timestamptz not null default now(),
  created_by uuid references users (id) on delete set null,
  primary key (decision_session_id, capability_id)
);

comment on table decision_session_capabilities is
  'The required capabilities implied by a session''s business goal(s) — pure junction/current-state table, not independently soft-deletable: a capability requirement is either part of the session right now or it isn''t. The session''s eventual decision_report is the durable historical record, not this table.';

create index decision_session_capabilities_capability_idx on decision_session_capabilities (capability_id);
create index decision_session_capabilities_created_by_idx on decision_session_capabilities (created_by);

alter table decision_session_capabilities enable row level security;
create policy decision_session_capabilities_all on decision_session_capabilities
  for all using (
    exists (
      select 1 from decision_sessions s
      where s.id = decision_session_capabilities.decision_session_id
        and s.deleted_at is null
        and is_org_member(s.organization_id)
    )
  );

-- ---------------------------------------------------------------------------

create table requirements (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  decision_session_id uuid not null references decision_sessions (id) on delete cascade,
  capability_id uuid references capabilities (id) on delete set null,
  title text not null,
  description text,
  is_mandatory boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint requirements_title_not_blank check (btrim(title) <> '')
);

comment on table requirements is
  'A specific, session-authored requirement (e.g. "Must support row-level security for EU entities"), optionally traced back to a capability from the shared taxonomy. Distinct from decision_session_capabilities: capabilities are which capability areas matter; requirements are the concrete, often free-text specifics within them.';

create index requirements_session_idx on requirements (decision_session_id) where deleted_at is null;
create index requirements_org_idx on requirements (organization_id) where deleted_at is null;
create index requirements_capability_idx on requirements (capability_id) where deleted_at is null;
create index requirements_created_by_idx on requirements (created_by);
create trigger requirements_set_updated_at before update on requirements for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table session_constraints (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  decision_session_id uuid not null references decision_sessions (id) on delete cascade,
  constraint_type constraint_type not null,
  value text not null,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null,
  constraint session_constraints_value_not_blank check (btrim(value) <> '')
);

comment on table session_constraints is
  'Budget, timeline, risk appetite, and similar bounding factors for a session. `value` is free text rather than one SQL enum per constraint_type (today''s wizard uses small fixed vocabularies like BudgetLevel/RiskAppetite per type, but those belong to the application layer''s validation, not a database-level type per row).';

create index session_constraints_session_idx on session_constraints (decision_session_id) where deleted_at is null;
create index session_constraints_org_idx on session_constraints (organization_id) where deleted_at is null;
create index session_constraints_created_by_idx on session_constraints (created_by);
create trigger session_constraints_set_updated_at before update on session_constraints for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table recommendations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  decision_session_id uuid not null references decision_sessions (id) on delete cascade,
  product_id uuid not null references products (id) on delete restrict,
  rank smallint not null,
  overall_score numeric(5,2) not null check (overall_score between 0 and 100),
  summary text,
  is_primary boolean not null default false,
  generated_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null
);

comment on table recommendations is
  'One ranked platform option for a session (the "Recommended Platforms" and "Alternatives" of today''s executive report are both rows here, distinguished by rank/is_primary). product_id uses ON DELETE RESTRICT, not CASCADE: a catalog product must not silently vanish from a customer''s historical recommendation record.';

create unique index recommendations_session_product_key
  on recommendations (decision_session_id, product_id) where deleted_at is null;
create index recommendations_session_idx on recommendations (decision_session_id) where deleted_at is null;
create index recommendations_product_idx on recommendations (product_id) where deleted_at is null;
create index recommendations_org_idx on recommendations (organization_id) where deleted_at is null;
create index recommendations_created_by_idx on recommendations (created_by);
create trigger recommendations_set_updated_at before update on recommendations for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table decision_scores (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  recommendation_id uuid not null references recommendations (id) on delete cascade,
  dimension_key score_dimension_key not null,
  score numeric(5,2) not null check (score between 0 and 100),
  weight numeric(4,3) not null check (weight between 0 and 1),
  positive_evidence text[] not null default '{}',
  negative_evidence text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null
);

comment on table decision_scores is
  'The per-dimension breakdown behind one recommendation''s overall_score — the persistence target for scoring/types.ts DimensionResult. weight is copied from decision_framework_dimensions at generation time (not looked up live), so a later change to a framework''s weights never silently rewrites the meaning of a past report.';

create unique index decision_scores_recommendation_dimension_key
  on decision_scores (recommendation_id, dimension_key) where deleted_at is null;
create index decision_scores_recommendation_idx on decision_scores (recommendation_id) where deleted_at is null;
create index decision_scores_org_idx on decision_scores (organization_id) where deleted_at is null;
create index decision_scores_created_by_idx on decision_scores (created_by);
create trigger decision_scores_set_updated_at before update on decision_scores for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table decision_reports (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  decision_session_id uuid not null references decision_sessions (id) on delete cascade,
  executive_summary text,
  -- Structured report body (current situation, decision drivers, risks,
  -- next steps, etc.) kept as jsonb rather than a fixed set of columns: the
  -- report's section list is still evolving (see docs/sprint-3.md,
  -- "Executive Report v2") and jsonb lets it keep evolving without a
  -- migration for every new section.
  full_report jsonb not null default '{}'::jsonb,
  generated_at timestamptz not null default now(),
  exported_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  created_by uuid references users (id) on delete set null
);

comment on table decision_reports is
  'The final, shareable artifact for a session. A session can accumulate more than one report row over time (e.g. regenerated after new requirements are added) — this table is an append-only history of report versions, not a single mutable "current report" field on decision_sessions.';

create index decision_reports_session_idx on decision_reports (decision_session_id) where deleted_at is null;
create index decision_reports_org_idx on decision_reports (organization_id) where deleted_at is null;
create index decision_reports_created_by_idx on decision_reports (created_by);
create trigger decision_reports_set_updated_at before update on decision_reports for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

-- Evidence is global reference data (the same citation can support scores
-- across many organizations' sessions), same pattern as analyst_reports.
create table evidence_sources (
  id uuid primary key default gen_random_uuid(),
  analyst_report_id uuid references analyst_reports (id) on delete set null,
  title text not null,
