-- ============================================================================

-- ClouDonna Platform — Phase 15
-- Migration: billing foundation (schema only — no data, no provider keys)
--
-- Purely additive: no existing table is touched. Every table here is
-- empty on creation and stays empty until a real payment provider is
-- configured and a Stripe (or invoice) checkout actually completes —
-- nothing in this migration or anywhere else in this sprint inserts a
-- row into any table below. See docs/commercial/01-billing-architecture.md
-- for the full design and the gates that must pass before that changes.
--
-- Hangs off `organization_id`, exactly like every other tenant-scoped
-- table in this schema (decisions, projects, workspaces) — a
-- subscription belongs to an organization, never to an individual user,
-- consistent with is_org_member()/is_org_admin() already being the
-- established RLS predicates (supabase/migrations/20260806120200_tenancy.sql).

-- ---------------------------------------------------------------------------
-- Plans — identifiers only. No price/currency column exists yet:
-- pricing has not been Founder-approved (docs/commercial/01-billing-
-- architecture.md §10), and a nullable price column that is always null
-- is worse than no column at all. Add pricing in a dedicated later
-- migration once real Stripe Price objects exist to reference.

create type billing_plan_code as enum ('founding_access', 'professional', 'team', 'enterprise');

create table plans (
  id uuid primary key default gen_random_uuid(),
  code billing_plan_code not null unique,
  display_name text not null,
  is_purchasable boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint plans_display_name_not_blank check (btrim(display_name) <> '')
);

comment on table plans is
  'Commercial plan identifiers only — no price. is_purchasable is false for every row until Founder Commercial Approval (docs/commercial/01-billing-architecture.md, Commercial Activation Gate); it exists so a future checkout page can filter to purchasable plans without a code change.';

create trigger plans_set_updated_at
  before update on plans
  for each row execute function set_updated_at();

insert into plans (code, display_name, is_purchasable) values
  ('founding_access', 'Founding Access', false),
  ('professional', 'Professional', false),
  ('team', 'Team', false),
  ('enterprise', 'Enterprise', false);

-- ---------------------------------------------------------------------------
-- Entitlement catalog — the vocabulary plan_entitlements below is allowed
-- to reference. Keeps a typo'd entitlement key a foreign-key violation
-- at insert time, not a silent no-op read later.

create type entitlement_value_type as enum ('boolean', 'integer');

create table entitlement_definitions (
  key text primary key,
  description text not null,
  value_type entitlement_value_type not null,
  constraint entitlement_definitions_key_not_blank check (btrim(key) <> '')
);

comment on table entitlement_definitions is
  'Catalog of entitlement keys capabilities can check (see apps/web/src/lib/entitlements/). Matches the examples enumerated in docs/commercial/01-billing-architecture.md §5 exactly — add a row here before any plan_entitlements row can reference a new key.';

insert into entitlement_definitions (key, description, value_type) values
  ('decision_memory', 'Access to saved Decision Memory (persisted decisions and version history).', 'boolean'),
  ('decision_replay', 'Access to Decision Replay (re-executing the engine against historical input). Not yet built as a product capability — no plan should grant this until it exists.', 'boolean'),
  ('evidence_intelligence', 'Access to evidence-backed AI narrative enrichment.', 'boolean'),
  ('executive_reports', 'Access to exportable executive-level report generation.', 'boolean'),
  ('api_access', 'Programmatic API access to Decision Intelligence data.', 'boolean'),
  ('advanced_governance', 'Advanced governance controls (approval workflows, audit export, custom roles).', 'boolean'),
  ('max_users', 'Maximum number of organization members.', 'integer'),
  ('max_workspaces', 'Maximum number of workspaces per organization.', 'integer'),
  ('max_decisions_per_month', 'Maximum number of new decisions per calendar month.', 'integer');

-- ---------------------------------------------------------------------------
-- Plan → entitlement mapping. Publicly readable (see RLS below) — this
-- is a capability catalog, not sensitive commercial data (no price
-- lives here).

create table plan_entitlements (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references plans (id) on delete cascade,
  entitlement_key text not null references entitlement_definitions (key) on delete cascade,
  boolean_value boolean,
  integer_value integer,
  created_at timestamptz not null default now(),
  constraint plan_entitlements_plan_key_unique unique (plan_id, entitlement_key),
  constraint plan_entitlements_value_shape check (
    (boolean_value is not null and integer_value is null)
    or (boolean_value is null and integer_value is not null)
  )
);

comment on table plan_entitlements is
  'What each plan grants. Deliberately empty on creation — no entitlement bundle has been Founder-approved per plan yet. apps/web/src/lib/entitlements/resolver.ts falls back to a hardcoded Founding Tester bundle for every organization until rows exist here AND a subscription references them, so this table being empty does not mean the product has no entitlements today — it means every organization currently gets the same fixed bundle, not a plan-derived one.';

-- ---------------------------------------------------------------------------
-- Billing customer — one per organization, holds the opaque provider
-- customer reference. Never a payment credential (see table comment).

create table billing_customers (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null unique references organizations (id) on delete cascade,
  billing_provider text not null default 'stripe',
  billing_provider_customer_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references users (id) on delete set null
);

comment on table billing_customers is
  'One row per organization once it first touches billing (created on first checkout session, or manually for an Enterprise invoice customer). billing_provider_customer_id is an opaque Stripe Customer id, never a payment credential — card data, CVC, and wallet tokens are never stored anywhere in this schema; Stripe holds every credential, this table holds only a reference to Stripe''s own record.';

create index billing_customers_provider_customer_idx on billing_customers (billing_provider, billing_provider_customer_id);

create trigger billing_customers_set_updated_at
  before update on billing_customers
  for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------
-- Subscriptions — the field list matches docs/commercial/01-billing-
-- architecture.md §8 and the brief's own BILLING DATA MODEL section
-- exactly: current_period_start/end, cancel_at_period_end, no more.

create type billing_subscription_status as enum (
  'trialing', 'active', 'past_due', 'canceled', 'incomplete', 'incomplete_expired', 'unpaid'
);

create table subscriptions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id) on delete cascade,
  billing_customer_id uuid not null references billing_customers (id) on delete cascade,
  plan_id uuid not null references plans (id),
  status billing_subscription_status not null,
  billing_provider_subscription_id text,
  current_period_start timestamptz,
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references users (id) on delete set null
);

comment on table subscriptions is
  'Subscription state as last reported by the billing provider''s webhooks — never written from a client-trusted "payment successful" signal (docs/commercial/01-billing-architecture.md §9). billing_provider_subscription_id is null for invoice/Enterprise subscriptions (billing_customers.billing_provider = ''invoice''), which never touch Stripe at all.';

-- At most one "live" subscription per organization at a time. A
-- canceled/incomplete_expired row does not block a new one, so
-- re-subscribing after cancellation is a normal insert, not an update
-- of the old row.
create unique index subscriptions_org_active_unique on subscriptions (organization_id)
  where status in ('trialing', 'active', 'past_due');

create index subscriptions_org_idx on subscriptions (organization_id);
create index subscriptions_provider_subscription_idx on subscriptions (billing_provider_subscription_id);

create trigger subscriptions_set_updated_at
  before update on subscriptions
  for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------
-- Webhook idempotency ledger. No end-user-facing role can read or write
-- this table at all (see RLS below) — only the service-role client used
-- exclusively by the future /api/billing/webhooks route handler
-- (docs/commercial/01-billing-architecture.md §9), never anything
-- reachable from a client component. This is the one documented,
-- deliberate use of a service-role key in this codebase — Sprint 6.1's
-- security review explicitly deferred introducing one until a real need
-- existed (docs/sprint-6/08-security.md); this is that need, and it
-- stays isolated to this single future route.

create table billing_webhook_events (
  id uuid primary key default gen_random_uuid(),
  billing_provider text not null default 'stripe',
  provider_event_id text not null,
  event_type text not null,
  received_at timestamptz not null default now(),
  processed_at timestamptz,
  payload_json jsonb not null,
  constraint billing_webhook_events_provider_event_unique unique (billing_provider, provider_event_id)
);

comment on table billing_webhook_events is
  'Idempotency ledger for billing-provider webhook deliveries. The unique (billing_provider, provider_event_id) constraint makes a duplicate/replayed delivery a no-op insert failure, caught before any subscriptions/billing_customers write runs, rather than a double-applied state change.';

create index billing_webhook_events_received_idx on billing_webhook_events (received_at);

-- ---------------------------------------------------------------------------
-- Row level security

alter table plans enable row level security;
alter table entitlement_definitions enable row level security;
alter table plan_entitlements enable row level security;
alter table billing_customers enable row level security;
alter table subscriptions enable row level security;
alter table billing_webhook_events enable row level security;

-- plans / entitlement_definitions / plan_entitlements: public capability
-- catalog, no price or customer data — readable by any authenticated
-- user, no write policy for any authenticated role (managed by a future
-- admin tool or migration, not self-service).
create policy plans_select on plans
  for select using (true);

create policy entitlement_definitions_select on entitlement_definitions
  for select using (true);

create policy plan_entitlements_select on plan_entitlements
  for select using (true);

-- billing_customers / subscriptions: admin-only within the owning
-- organization — billing is a management action, not a general team
-- action (docs/commercial/01-billing-architecture.md §8). No INSERT/
-- UPDATE/DELETE policy for the authenticated role on either table: every
-- write is either the webhook handler (service-role, bypasses RLS by
-- design) or a future admin-invoked security-definer RPC, never a
-- direct client write — a compromised or buggy client can never
-- fabricate an "active" subscription.
create policy billing_customers_select on billing_customers
  for select using (is_org_admin(organization_id));

create policy subscriptions_select on subscriptions
  for select using (is_org_admin(organization_id));

-- billing_webhook_events: no policy at all for any role — RLS enabled
-- with zero policies means every authenticated/anon request is denied
-- by default; only a service-role client (which bypasses RLS entirely,
-- per Supabase's standard behavior) can ever touch this table.

-- ============================================================================
-- SOURCE: supabase/migrations/20260809090000_inquiries.sql
-- ============================================================================

-- ClouDonna Platform — Business Operations
-- Migration: first-party Inquiry System + platform staff
--
-- The single backend for every public contact/lead-capture surface —
-- /contact, the homepage Founding Testers section, /early-access,
-- /for-vendors, /for-partners all write here through one API route
-- (apps/web/src/app/api/inquiries/route.ts). Replaces the previous
-- EarlyAccess component's simulated submission (setTimeout, nothing
-- transmitted or stored) with a real, persisted workflow.
--
-- Deliberately excludes any field for decision content, evidence, or
-- org/workspace data — there is no column here an inquiry could carry
-- that kind of data through, by construction, not by convention.

create type inquiry_type as enum (
  'founding_tester',
  'enterprise_pilot',
  'customer',
  'partner',
  'vendor',
  'general'
);

create type inquiry_status as enum ('new', 'in_review', 'responded', 'closed', 'spam');

create table inquiries (
  id uuid primary key default gen_random_uuid(),
  inquiry_type inquiry_type not null,
  name text not null,
  business_email text not null,
  company text,
  role text,
  country text,
  phone text,
  message text,
  source_page text,
  utm_source text,
  utm_campaign text,
  referrer text,
  status inquiry_status not null default 'new',
  owner uuid references profiles (id) on delete set null,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint inquiries_name_not_blank check (btrim(name) <> ''),
  constraint inquiries_email_format check (business_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$')
);

comment on table inquiries is
  'The one first-party inquiry backend for every public contact surface. Public INSERT (anon + authenticated), staff-only SELECT/UPDATE, no DELETE policy at all — a submitted inquiry is never removed, only ever moved to status=closed/spam, so the record stays a real audit trail. Never holds decision content: the column set is fixed and there is no field an evidence/decision payload could land in.';

create index inquiries_status_idx on inquiries (status);
create index inquiries_type_idx on inquiries (inquiry_type);
create index inquiries_created_at_idx on inquiries (created_at desc);
create index inquiries_owner_idx on inquiries (owner);

create trigger inquiries_set_updated_at
  before update on inquiries
  for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------
-- Platform staff — who is allowed to see/manage inquiries. Deliberately
-- separate from organization_members: platform operations (ClouDonna
-- running its own business) and customer tenancy (an org using the
-- product) are different concerns, and conflating them would mean
-- "founder views leads" and "customer manages their org" share one
-- privilege model for no good reason. Empty on creation — seeding the
-- first row is a manual, one-time founder action (documented in
-- docs/operations/01-business-operations.md), not something this
-- migration can do without inventing a real user id.

create table platform_staff (
  user_id uuid primary key references profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);

comment on table platform_staff is
  'Grants Founder Dashboard access. Empty until a founder is manually added — see docs/operations/01-business-operations.md, "Seeding the first platform staff member."';

create or replace function is_platform_staff()
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from platform_staff s where s.user_id = auth.uid()
  );
$$;

comment on function is_platform_staff() is
  'RLS predicate: true if the current auth.uid() is a seeded platform staff member. Mirrors is_org_admin()''s shape exactly, for a platform-level rather than org-level privilege.';

-- ---------------------------------------------------------------------------
-- Row level security

alter table inquiries enable row level security;
alter table platform_staff enable row level security;

-- Public write, staff-only read/manage. No DELETE policy for any role —
-- inquiries are closed, never removed.
create policy inquiries_insert_public on inquiries
  for insert to anon, authenticated
  with check (true);

create policy inquiries_select_staff on inquiries
  for select using (is_platform_staff());

create policy inquiries_update_staff on inquiries
  for update using (is_platform_staff());

-- platform_staff: no policy for any role — RLS-closed by default, same
-- pattern as billing_webhook_events. is_platform_staff() reads it via
-- security definer regardless; nothing else needs to.

-- ============================================================================
-- SOURCE: supabase/migrations/20260809100000_vendor_intelligence_registry.sql
-- ============================================================================

-- ClouDonna Platform — Vendor Intelligence Registry (Phase 3, architecture only)
--
-- Purely additive, references the existing Sprint 4 catalog (vendors,
-- products, capabilities) rather than recreating it — those tables
-- already cover the "Vendor / Product / Capability" entities named in
-- this phase's brief. What's genuinely missing, and what this migration
-- adds, is the provenance layer: where does a fact come from, when was
-- it observed, has it been verified, and what's the registry of
-- official sources per vendor to (eventually) check for updates.
--
-- No ingestion code ships with this migration — see
-- docs/operations/03-vendor-intelligence-architecture.md for the
-- provider-based framework design. This is schema only, and it is
-- empty on creation: nothing crawls anything as a result of this file
-- existing.

create type vendor_source_type as enum (
  'official_website',
  'official_documentation',
  'official_api_reference',
  'official_release_notes',
  'official_blog',
  'rss_feed'
);

create table vendor_sources (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references vendors (id) on delete cascade,
  source_type vendor_source_type not null,
  url text not null,
  title text,
  last_verified_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references users (id) on delete set null,
  constraint vendor_sources_url_not_blank check (btrim(url) <> '')
);

comment on table vendor_sources is
  'The registry of official sources a vendor is checked against — "official sources, documentation, release notes, API references, RSS" from the Phase 3 brief. last_verified_at is null until a real ingestion pass runs (none exists yet); this table can be populated and reviewed manually before any automated checking is built.';

create unique index vendor_sources_vendor_url_key on vendor_sources (vendor_id, url);
create index vendor_sources_vendor_idx on vendor_sources (vendor_id);

create trigger vendor_sources_set_updated_at
  before update on vendor_sources
  for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create type evidence_signal_type as enum (
  'documentation',
  'release_notes',
  'benchmark',
  'community_signal',
  'partner_signal',
  'general'
);

create table vendor_evidence (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references vendors (id) on delete cascade,
  product_id uuid references products (id) on delete cascade,
  capability_id uuid references capabilities (id) on delete set null,
  source_id uuid references vendor_sources (id) on delete set null,
  signal_type evidence_signal_type not null default 'general',
  fact text not null,
  source_url text,
  source_title text,
  observed_at timestamptz not null default now(),
  published_at timestamptz,
  reliability evidence_reliability_tier not null,
  verification_status verification_status not null default 'unverified',
  confidence numeric(3, 2) check (confidence is null or (confidence >= 0 and confidence <= 1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references users (id) on delete set null,
  constraint vendor_evidence_fact_not_blank check (btrim(fact) <> '')
);

comment on table vendor_evidence is
  'Every extracted fact, with full provenance — fact/vendor/product/capability/source/source_url/source_title/observed_at/published_at/confidence/verification_status, exactly the field list the Phase 3 brief specifies. This is what lets Donna eventually answer "where did this information originate, and when was it last verified" — the question the brief poses directly. reliability and verification_status reuse the exact enums Sprint 4 already defined for analyst_reports/customer_references, not a parallel taxonomy.';

create index vendor_evidence_vendor_idx on vendor_evidence (vendor_id);
create index vendor_evidence_product_idx on vendor_evidence (product_id);
create index vendor_evidence_capability_idx on vendor_evidence (capability_id);
create index vendor_evidence_verification_idx on vendor_evidence (verification_status);

create trigger vendor_evidence_set_updated_at
  before update on vendor_evidence
  for each row execute function set_updated_at();

-- ---------------------------------------------------------------------------

create table vendor_source_change_log (
  id uuid primary key default gen_random_uuid(),
  source_id uuid not null references vendor_sources (id) on delete cascade,
  changed_at timestamptz not null default now(),
  change_summary text not null,
  constraint vendor_source_change_log_summary_not_blank check (btrim(change_summary) <> '')
);

comment on table vendor_source_change_log is
  '"Change history" from the Phase 3 brief — a append-only log of what changed at a given source and when noticed. Empty until a real ingestion or manual-review pass exists to write to it.';

create index vendor_source_change_log_source_idx on vendor_source_change_log (source_id, changed_at desc);

-- ---------------------------------------------------------------------------
-- Row level security — public read (this is catalog data, same posture
-- as vendors/products themselves), write restricted to org admins for
-- now (mirrors product_capabilities' existing pattern: public SELECT,
-- no public write policy — inserts are an internal/admin operation
-- until a real vendor-submission review flow exists, see /for-vendors
-- prep below).

alter table vendor_sources enable row level security;
alter table vendor_evidence enable row level security;
alter table vendor_source_change_log enable row level security;

create policy vendor_sources_select on vendor_sources for select using (true);
create policy vendor_evidence_select on vendor_evidence for select using (true);
create policy vendor_source_change_log_select on vendor_source_change_log for select using (true);

-- No INSERT/UPDATE/DELETE policy for any role on any of the three
-- tables above — populating the registry is an internal, reviewed
-- operation (a future admin tool or direct migration), never a public
-- or even a plain-authenticated write, consistent with "vendor
-- submissions never affect rankings automatically... every submission
-- enters review" from the Phase 3 brief.

-- ============================================================================
-- SOURCE: supabase/migrations/20260809120000_inquiries_taxonomy_refinement.sql
-- ============================================================================

-- ClouDonna Platform — Business Operations refinement
--
-- Aligns the inquiries table built in 20260809090000_inquiries.sql with
-- the finalized taxonomy: inquiry_type collapses enterprise_pilot/
-- customer into a single `enterprise`; status moves from the original
-- new/in_review/responded/closed/spam vocabulary to
-- new/reviewing/contacted/qualified/closed. Postgres cannot remove enum
-- values in place, so this recreates both enums and migrates the
-- column via USING — safe here because the original migration has
-- never been applied to a live database (no local Postgres available
-- all sprint, disclosed since Sprint 6.2 Slice C), so there is no real
-- data to actually migrate, only the shape to correct before it ever
-- is applied.
--
-- Also: adds utm_medium (present in the finalized field list, missing
-- before), and drops owner/notes — the finalized field list doesn't
-- include them, and carrying columns the current spec doesn't call for
-- is clutter, not a hedge. Status changes are now the only staff
-- mutation this table supports, matching Phase 10's "this is an inbox,
-- nothing more."

alter table inquiries alter column status drop default;

alter type inquiry_type rename to inquiry_type_old;
create type inquiry_type as enum ('founding_tester', 'enterprise', 'partner', 'vendor', 'general');

alter type inquiry_status rename to inquiry_status_old;
create type inquiry_status as enum ('new', 'reviewing', 'contacted', 'qualified', 'closed');

alter table inquiries
  alter column inquiry_type type inquiry_type using (
    case inquiry_type::text
      when 'enterprise_pilot' then 'enterprise'
      when 'customer' then 'enterprise'
      else inquiry_type::text
    end
  )::inquiry_type,
  alter column status type inquiry_status using (
    case status::text
      when 'in_review' then 'reviewing'
      when 'responded' then 'contacted'
      when 'spam' then 'closed'
      else status::text
    end
  )::inquiry_status;

alter table inquiries alter column status set default 'new';

drop type inquiry_type_old;
drop type inquiry_status_old;

alter table inquiries add column utm_medium text;

alter table inquiries drop column owner;
alter table inquiries drop column notes;

comment on table inquiries is
  'The one first-party inquiry backend for every public contact surface. Public INSERT (anon + authenticated), staff-only SELECT/UPDATE, no DELETE policy at all. Field list and taxonomy finalized in docs/operations/05-inquiry-system-v2.md — this is the authoritative shape going forward.';

-- ---------------------------------------------------------------------------
-- Rate limiting — a narrow, count-only security-definer function so an
-- anonymous caller can be rate-limited WITHOUT being granted any SELECT
-- access to the inquiries table itself (RLS still denies that
-- completely). Returns a count only, never rows, never other
-- submitters' data.

create or replace function count_recent_inquiries_by_email(p_email text, p_window interval default interval '1 hour')
returns integer
language sql
security definer
stable
set search_path = public
as $$
  select count(*)::integer
  from inquiries
  where business_email = p_email
    and created_at > now() - p_window;
$$;

comment on function count_recent_inquiries_by_email(text, interval) is
  'The one narrow read an anonymous caller is allowed against inquiries — a count for its own submitted email, over a window, nothing else. Backs the application-level rate limit in apps/web/src/lib/inquiries/handler.ts; RLS on the table itself still denies every other read for anon.';

-- ============================================================================
-- SOURCE: supabase/migrations/20260809130000_business_events.sql
-- ============================================================================

-- ClouDonna Platform — first-party business events
--
-- Phase 11's own framing: "first-party business events only... do not
-- install third-party visitor intelligence... do not send private
-- Donna or Decision data into analytics." This table IS the first-party
-- destination — our own Postgres, nothing external, nothing sent to a
-- vendor. Deliberately anonymous and write-mostly: no user id, no
-- session id, no IP address, nothing that could re-identify a visitor.
-- If that's ever needed, it's a new, explicit decision — not something
-- this table quietly grows into.

create type business_event_name as enum (
  'contact_viewed',
  'inquiry_started',
  'inquiry_submitted',
  'founding_tester_submitted',
  'partner_inquiry_submitted',
  'vendor_inquiry_submitted'
);

create table business_events (
  id uuid primary key default gen_random_uuid(),
  event_name business_event_name not null,
  source_page text,
  properties jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

comment on table business_events is
  'First-party-only event log for the six named business events in docs/operations/05-inquiry-system-v2.md. No visitor identity of any kind — no user id, session id, or IP. Not a general-purpose analytics table: adding a new event name means editing business_event_name deliberately, not passing an arbitrary string through from the client.';

create index business_events_name_idx on business_events (event_name);
create index business_events_created_at_idx on business_events (created_at desc);

alter table business_events enable row level security;

-- Public write (any visitor can log one of the six named events), no
-- SELECT policy for anon/authenticated — reading this data back is a
-- staff-only, future reporting concern, not needed by anything today.
create policy business_events_insert_public on business_events
  for insert to anon, authenticated
  with check (true);

create policy business_events_select_staff on business_events
  for select using (is_platform_staff());

commit;
